/**
 * Pure helpers behind `bun scripts/lintBaseline.ts`. Two generated files describe the accepted lint debt:
 *
 * - .oxlintrc.baseline.json: one override per rule turning it off in the files that violate it. This is
 *   what makes `bun run lint` pass; oxlint reads it, nothing else does.
 * - .oxlintrc.baseline.counts.json: violations per rule per file. This is the source of truth for the
 *   ratchet checks, because an override hides every violation of a rule in a file, not just the ones
 *   that existed when it was written.
 */

export interface Diagnostic {
	filename: string
	code: string
}

/** rule -> file -> number of violations */
export type Counts = Record<string, Record<string, number>>

export function countViolations(diagnostics: Array<Diagnostic>): Counts {
	const counts: Counts = {}
	for (const diagnostic of diagnostics) {
		// "react(refs)" -> "react/refs"; "eslint(no-empty)" -> "no-empty"
		const match = /^([a-z0-9-]+)\((.+)\)$/.exec(diagnostic.code)
		if (!match) continue
		const rule = match[1] === 'eslint' ? match[2] : `${match[1]}/${match[2]}`
		const files = (counts[rule] ??= {})
		files[diagnostic.filename] = (files[diagnostic.filename] ?? 0) + 1
	}
	return counts
}

// Override globs are matched as globs, so literal glob characters in paths must be escaped.
function escapeGlob(path: string): string {
	return path.replace(/[[\]{}*?!]/g, (char) => `\\${char}`)
}

function sortedKeys(record: Record<string, unknown>): Array<string> {
	return Object.keys(record).sort()
}

export function renderBaseline(counts: Counts, ignorePatterns: Array<string>): string {
	const overrides = sortedKeys(counts).map((rule) => ({
		files: sortedKeys(counts[rule]).map(escapeGlob),
		rules: { [rule]: 'off' }
	}))
	const config = {
		$schema: './node_modules/oxlint/configuration_schema.json',
		extends: ['./.oxlintrc.json'],
		// `extends` does not inherit ignorePatterns, so the walk would otherwise include public/ and .next/.
		ignorePatterns,
		overrides
	}
	return `// Generated by \`bun run lint:baseline\`. Do not edit: fix the violations and regenerate.\n${JSON.stringify(config, null, '\t')}\n`
}

/**
 * The committed sidecar is file-major with one line per file, so fixing a file changes one line and the
 * file stays as small as the number of files with debt.
 */
export function renderCounts(counts: Counts): string {
	const byFile: Record<string, Record<string, number>> = {}
	for (const rule in counts) {
		for (const file in counts[rule]) (byFile[file] ??= {})[rule] = counts[rule][file]
	}
	const lines = sortedKeys(byFile).map((file) => {
		const rules: Record<string, number> = {}
		for (const rule of sortedKeys(byFile[file])) rules[rule] = byFile[file][rule]
		return `\t${JSON.stringify(file)}: ${JSON.stringify(rules)}`
	})
	return `{\n${lines.join(',\n')}\n}\n`
}

export function parseCounts(text: string): Counts {
	const byFile = JSON.parse(text) as Record<string, Record<string, number>>
	const counts: Counts = {}
	for (const file in byFile) {
		for (const rule in byFile[file]) (counts[rule] ??= {})[file] = byFile[file][rule]
	}
	return counts
}

/**
 * Entries where `head` accepts more debt than `base`: a rule/file pair that is new, or whose count went
 * up. Used both for "committed baseline vs. the target branch" (regenerating must not bake in new
 * violations) and for "current violations vs. committed baseline" (an override hides extra violations
 * of the same rule in the same file, so lint alone cannot see them).
 */
export function findGrowth(base: Counts, head: Counts): Array<string> {
	const grown: Array<string> = []
	for (const rule of sortedKeys(head)) {
		for (const file of sortedKeys(head[rule])) {
			const before = base[rule]?.[file] ?? 0
			const after = head[rule][file]
			if (after > before) grown.push(`${rule}  ${file}  ${before} -> ${after}`)
		}
	}
	return grown
}

/** Entries in `committed` that `fresh` no longer needs, fully or partly. */
export function findStale(committed: Counts, fresh: Counts): Array<string> {
	const stale: Array<string> = []
	for (const rule of sortedKeys(committed)) {
		for (const file of sortedKeys(committed[rule])) {
			const before = committed[rule][file]
			const after = fresh[rule]?.[file] ?? 0
			if (after < before) stale.push(`${rule}  ${file}  ${before} -> ${after}`)
		}
	}
	return stale
}

export function total(counts: Counts): { rules: number; files: number; violations: number } {
	const files = new Set<string>()
	let violations = 0
	for (const rule in counts) {
		for (const file in counts[rule]) {
			files.add(file)
			violations += counts[rule][file]
		}
	}
	return { rules: Object.keys(counts).length, files: files.size, violations }
}
